import re

class Solution:
    def generateTag(self, caption: str) -> str:
        words = re.findall(r'[a-zA-Z0-9]+', caption)
        if not words:
            return ""
        capitalized = [w.capitalize() for w in words]
        tag = "#" + "".join(capitalized)
        return tag[:100]

#include <string>
#include <vector>
#include <cctype>

class Solution {
public:
    std::string generateTag(std::string caption) {
        std::vector<std::string> words;
        std::string curr = "";
        for (char ch : caption) {
            if (std::isalnum(ch)) {
                curr += ch;
            } else {
                if (!curr.empty()) {
                    words.push_back(curr);
                    curr = "";
                }
            }
        }
        if (!curr.empty()) words.push_back(curr);
        if (words.empty()) return "";

        std::string tag = "#";
        for (auto& w : words) {
            w[0] = std::toupper(w[0]);
            for (size_t i = 1; i < w.size(); ++i) w[i] = std::tolower(w[i]);
            tag += w;
            if (tag.size() >= 100) break;
        }
        if (tag.size() > 100) tag = tag.substr(0, 100);
        return tag;
    }
};

class Solution {
    public String generateTag(String caption) {
        StringBuilder sb = new StringBuilder();
        StringBuilder word = new StringBuilder();

        for (int i = 0; i < caption.length(); i++) {
            char ch = caption.charAt(i);
            if (Character.isLetterOrDigit(ch)) {
                word.append(ch);
            } else {
                if (word.length() > 0) {
                    appendCapitalized(sb, word.toString());
                    word.setLength(0);
                }
            }
        }
        if (word.length() > 0) {
            appendCapitalized(sb, word.toString());
        }

        if (sb.length() == 0) return "";
        String res = "#" + sb.toString();
        return res.length() > 100 ? res.substring(0, 100) : res;
    }

    private void appendCapitalized(StringBuilder sb, String w) {
        sb.append(Character.toUpperCase(w.charAt(0)));
        for (int i = 1; i < w.length(); i++) {
            sb.append(Character.toLowerCase(w.charAt(i)));
        }
    }
}

/**
 * @param {string} caption
 * @return {string}
 */
var generateTag = function(caption) {
    const matches = caption.match(/[a-zA-Z0-9]+/g);
    if (!matches) return "";
    const words = matches.map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
    const tag = "#" + words.join("");
    return tag.slice(0, 100);
};
